BEGIN;
CREATE SCHEMA relaxed_test;
CREATE FUNCTION relaxed_test.assert(ok boolean,msg text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN IF ok IS DISTINCT FROM true THEN RAISE EXCEPTION 'ASSERT: %',msg;END IF;END $$;
CREATE FUNCTION relaxed_test.denied(statement text) RETURNS void LANGUAGE plpgsql AS $$ BEGIN BEGIN EXECUTE statement;EXCEPTION WHEN OTHERS THEN RETURN;END;RAISE EXCEPTION 'Expected rejection: %',statement;END $$;
GRANT USAGE ON SCHEMA relaxed_test TO anon,authenticated;GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA relaxed_test TO anon,authenticated;
INSERT INTO auth.users(id,email) VALUES('2a000000-0000-4000-8000-000000000001','relaxed@example.invalid');
INSERT INTO public.companies(id,nome,created_by) VALUES('1a000000-0000-4000-8000-000000000001','Relaxed fixture','2a000000-0000-4000-8000-000000000001');
INSERT INTO public.company_members(company_id,user_id,role,maintenance_role,created_by) VALUES('1a000000-0000-4000-8000-000000000001','2a000000-0000-4000-8000-000000000001','administrador','admin_empresa','2a000000-0000-4000-8000-000000000001');
SELECT set_config('request.jwt.claim.sub','2a000000-0000-4000-8000-000000000001',true);SET LOCAL ROLE authenticated;
SELECT set_config('relaxed_test.invite',public.maintenance_partner_requests_command('1a000000-0000-4000-8000-000000000001','rotate')->>'token',true);RESET ROLE;
SELECT set_config('relaxed_test.payload','{"request_id":"6a000000-0000-4000-8000-000000000001","edit_token":"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb","consent":true,"declaration":true,"base":{"razao_social":"Minimal workshop","cnpj_cpf":"11222333000181","tipo":"oficina_mecanica","whatsapp":"11987654321","tipos_veiculo_atendidos":[],"especialidades":[],"horario_funcionamento":{},"atende_24h":false,"possui_guincho":false,"valor_hora_mao_obra":0,"prazo_pagamento_dias":0,"desconto_percentual":0},"profile":{}}',true);
SELECT set_config('request.jwt.claim.sub','',true);SET LOCAL ROLE anon;
SELECT relaxed_test.assert(public.maintenance_partner_registration(current_setting('relaxed_test.invite'),'submit',current_setting('relaxed_test.payload')::jsonb)->>'can_complete'='true','minimal registration saved');
SELECT relaxed_test.assert(public.maintenance_partner_registration(current_setting('relaxed_test.invite'),'submit',current_setting('relaxed_test.payload')::jsonb)->>'can_complete'='true','retry preserves individual link');
SELECT relaxed_test.denied($q$SELECT * FROM public.maintenance_partner_requests$q$);
SELECT relaxed_test.denied($q$SELECT public.maintenance_partner_registration_edit(repeat('a',64),'load')$q$);
SELECT relaxed_test.assert(public.maintenance_partner_registration_edit(repeat('b',64),'load')->'base'->>'razao_social'='Minimal workshop','individual token retrieves own data');
SELECT relaxed_test.assert(public.maintenance_partner_registration_edit(repeat('b',64),'save',(current_setting('relaxed_test.payload')::jsonb-'edit_token'-'request_id')||'{"version":1,"profile":{"marcas":["Iveco"],"aceita_faturado":"Sim"}}')->>'status'='recebida','optional data saved later without payment term');
SELECT relaxed_test.denied($q$SELECT public.maintenance_partner_registration_edit(repeat('b',64),'save',(current_setting('relaxed_test.payload')::jsonb-'edit_token'-'request_id')||'{"version":1}')$q$);
SELECT relaxed_test.denied($q$SELECT public.maintenance_partner_registration_edit(repeat('b',64),'save',jsonb_set((current_setting('relaxed_test.payload')::jsonb-'edit_token'-'request_id')||'{"version":2}','{base,cnpj_cpf}','"12345678000195"'))$q$);
RESET ROLE;
SELECT relaxed_test.assert((SELECT edit_token_hash<>repeat('b',64) AND edit_version=2 AND payload->'profile'->'marcas'='["Iveco"]'::jsonb FROM public.maintenance_partner_requests WHERE request_id='6a000000-0000-4000-8000-000000000001'),'only token hash stored and latest payload saved');
SELECT relaxed_test.assert((SELECT count(*)=1 FROM public.maintenance_partner_request_audit WHERE action='complementada' AND company_id='1a000000-0000-4000-8000-000000000001'),'completion audited');
SELECT set_config('relaxed_test.id',(SELECT id::text FROM public.maintenance_partner_requests WHERE request_id='6a000000-0000-4000-8000-000000000001'),true);
SELECT set_config('request.jwt.claim.sub','2a000000-0000-4000-8000-000000000001',true);SET LOCAL ROLE authenticated;
SELECT relaxed_test.assert(public.maintenance_partner_requests_command('1a000000-0000-4000-8000-000000000001','approve',jsonb_build_object('id',current_setting('relaxed_test.id'),'note','Minimal accepted'))->>'status'='aprovada','incomplete partner can be approved');
RESET ROLE;SELECT set_config('request.jwt.claim.sub','',true);SET LOCAL ROLE anon;
SELECT relaxed_test.assert(public.maintenance_partner_registration_edit(repeat('b',64),'load')->>'editable'='false','reviewed data no longer editable');
SELECT relaxed_test.denied($q$SELECT public.maintenance_partner_registration_edit(repeat('b',64),'save',(current_setting('relaxed_test.payload')::jsonb-'edit_token'-'request_id')||'{"version":2}')$q$);
RESET ROLE;UPDATE public.maintenance_partner_requests SET edit_expires_at=now()-interval '1 hour' WHERE request_id='6a000000-0000-4000-8000-000000000001';SET LOCAL ROLE anon;
SELECT relaxed_test.denied($q$SELECT public.maintenance_partner_registration_edit(repeat('b',64),'load')$q$);
RESET ROLE;ROLLBACK;